INSERT INTO permissions (permission_id, name, api_path, http_method, module, created_at, updated_at, created_by, updated_by, version)
SELECT UUID(), 'Workspace create', '/api/v1/workspaces', 'POST', 'COLLAB', NOW(6), NOW(6), 'system', 'system', 0
WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE api_path = '/api/v1/workspaces' AND http_method = 'POST');

