INSERT INTO permission_roles (role_id, permission_id)
SELECT r.role_id, p.permission_id
FROM roles r
JOIN permissions p ON p.module = 'COLLAB'
WHERE r.name = 'ADMIN'
  AND NOT EXISTS (
      SELECT 1 FROM permission_roles pr
      WHERE pr.role_id = r.role_id AND pr.permission_id = p.permission_id
  );
